/** Houzz “h” blocks (Simple Icons). */
const houzz = svg(
  `<path fill="#4DBC15" d="M1.27 0V24H9.32V16.44H14.68V24H22.73V10.37L6.61 5.75V0H1.27Z"/>`,
);

/** Generic website / custom link — globe instead of a bare letter. */
const website = svg(
  `<circle cx="12" cy="12" r="10" fill="none" stroke="#475569" stroke-width="1.75"/>` +
  `<ellipse cx="12" cy="12" rx="4.5" ry="10" fill="none" stroke="#475569" stroke-width="1.5"/>` +
  `<path fill="none" stroke="#475569" stroke-width="1.5" d="M2.5 12h19M4.2 7.5h15.6M4.2 16.5h15.6"/>`,
);

const ICONS = {
  google,
  facebook,
  yelp,
  thumbtack,
  angi,
  nextdoor,
  bbb,
  houzz,
  other: website,
};

/** Tile background behind the mark. */
const TILE = {
  google: '#FFFFFF',
  facebook: '#FFFFFF',
  yelp: '#FFFFFF',
  thumbtack: '#FFFFFF',
  angi: '#FFFFFF',
  nextdoor: '#FFFFFF',
  bbb: '#FFFFFF',
  houzz: '#FFFFFF',
  other: '#F8FAFC',
};

function iconFor(key) {
  return ICONS[key] || '';
}

function tileFor(key) {
  return TILE[key] || '#F1F5F9';
}

module.exports = {
  ICONS,
  iconFor,
  tileFor,
};
